// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the keybindings list of reflex-kernel (reflex_kernel.keys_palette), like Omarchy's
//          SUPER+K menu: SHORTCUTS.KEYS (Alt+K, from shortcuts.py via window.SHORTCUTS) opens a
//          search box over every shortcut; typing filters the rows, arrows move, Enter runs the picked
//          shortcut when a key press alone can (data-keys-run; window.smashPress in panes.js), Esc / Alt+K / a
//          click outside closes. Listens on window in the capture phase, so it sees keys before
//          panes.js (document) and Esc closes this list, not a floating view under it.
// ---------------------------------------------------------------------------
(() => {
  const KEYS = (window.SHORTCUTS && window.SHORTCUTS.KEYS) || "Alt+K";

  // same matching as panes.js: exact modifiers, a letter by key position
  const matches = (event, combo) => {
    const parts = combo.split("+");
    const key = parts.pop();
    const mods = new Set(parts);
    if (event.altKey !== mods.has("Alt") || event.ctrlKey !== mods.has("Ctrl")
      || event.shiftKey !== mods.has("Shift") || event.metaKey !== mods.has("Meta")) return false;
    return /^[A-Z]$/.test(key) ? event.code === `Key${key}` : event.key === key;
  };

  const palette = () => document.querySelector("[data-keys]");
  const isOpen = () => palette()?.classList.contains("is-open");
  const rows = () => [...palette().querySelectorAll("[data-keys-row]")];
  const shown = () => rows().filter((row) => !row.hidden);
  const active = () => palette().querySelector("[data-keys-row].is-active");
  let before = null; // focus to give back on close

  const setActive = (row) => {
    rows().forEach((r) => r.classList.toggle("is-active", r === row));
    if (!row) return;
    const list = row.parentElement;
    if (row.offsetTop < list.scrollTop) list.scrollTop = row.offsetTop;
    else if (row.offsetTop + row.offsetHeight > list.scrollTop + list.clientHeight) {
      list.scrollTop = row.offsetTop + row.offsetHeight - list.clientHeight;
    }
  };
  const filter = () => {
    const words = palette().querySelector("[data-keys-search]").value.trim().toLowerCase().split(/\s+/).filter(Boolean);
    rows().forEach((row) => { row.hidden = !words.every((w) => row.dataset.keysRow.includes(w)); });
    palette().classList.toggle("is-empty", shown().length === 0);
    setActive(shown()[0] || null);
  };

  const open = () => {
    before = document.activeElement;
    const search = palette().querySelector("[data-keys-search]");
    search.value = "";
    palette().classList.add("is-open");
    filter();
    search.focus();
  };
  const close = () => {
    palette().classList.remove("is-open");
    if (before && before.isConnected) before.focus();
    before = null;
  };

  window.addEventListener("keydown", (event) => {
    if (!palette()) return;
    if (matches(event, KEYS)) {
      event.preventDefault();
      event.stopPropagation();
      return isOpen() ? close() : open();
    }
    // the command palette is above this list: its keys are its own (panes.js)
    if (!isOpen() || document.querySelector("[data-palette]")) return;
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close();
    } else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const list = shown();
      const at = list.indexOf(active());
      setActive(list[event.key === "ArrowDown" ? Math.min(at + 1, list.length - 1) : Math.max(at - 1, 0)] || null);
    } else if (event.key === "Enter") {
      event.preventDefault();
      // as in Omarchy's list: run the picked binding, where you were before the list opened
      const keys = active()?.dataset.keysRun;
      if (!keys) return;
      const from = before;
      close();
      window.smashPress?.(keys, from);
    }
  }, true);

  document.addEventListener("input", (event) => {
    if (event.target.matches?.("[data-keys-search]")) filter();
  });
  document.addEventListener("click", (event) => {
    if (event.target.closest?.("[data-keys-close]")) close();
  });
})();
